---@class CommonTabToggleUp
---@field Cell                          	UnityEngine.RectTransform
---@field Layout                        	UnityEngine.RectTransform
local CommonTabToggleUp = Class("CommonTabToggleUp")
function CommonTabToggleUp:__init()
    self.togglesData = {}
    self.selectIndex = -1
    self.cellEnvPath = CellEnvPath
end

function CommonTabToggleUp:__delete()
    self.controller = nil
    self.togglesData = nil
    self.selectIndex = nil
end

function CommonTabToggleUp:Awake()

end

function CommonTabToggleUp:CostumeCellEnvPath(path)
    self.cellEnvPath = path
end
---绘制左侧可点页签
---@param togglesData table 格式参考
