function CommonTabToggleUp:FillToggles(togglesData, openType)
    if not isNull(openType) then
        self.selectIndex = openType
    else
        self.selectIndex = 1--不穿的话默认打开第一个
    end
    self.togglesData = togglesData
    for i = 1, #self.togglesData do
        local tabGo
        --local redPointGo
        tabGo = self.Layout:Find("tabGo"..i)
        if not tabGo then
            tabGo = CfUtils.InstantiateGo(self.Cell, self.Layout)
            tabGo.name = "tabGo"..i
        end
        ---@type CommonTabToggleUpCell
        local env = CfUtils.GetLuaScr(tabGo, self.cellEnvPath)
        env:FreshBaseUI(self.togglesData[i])

        if self.togglesData[i].isLock then
            env:SetLockState(true)
        else
            env:SetLockState(false)
        end

        --if not isNull(env) then
        --    env:FreshBaseUI({
        --        text = self.togglesData[i].text,
        --        textColor = self.togglesData[i].textColor,--颜色参数可不传
        --        fontSize = self.togglesData[i].fontSize
        --    })
        --end
        --小红点
        -- if not isNull(self.togglesData[i].redPointStrNode) then
        --     GameUtils.BindRedPoint(self.togglesData[i].redPointStrNode, tabGo.gameObject, true)
        -- end
        --小红点
        env:FreshRedPointStatus(false)
        if not isNull(self.togglesData[i].redPointStrNode) then
            GameUtils.BindRedPoint(self.togglesData[i].redPointStrNode, tabGo.gameObject, true)
        elseif not isNull(self.togglesData[i].redPointStatus) then     --新增一个外部强行控制小红点的变量
            env:FreshRedPointStatus(checkBool(self.togglesData[i].redPointStatus))
        end
        --
        local isSelected = i == self.selectIndex
        env:FreshSelectStatus(isSelected)
        env:SetCallBack(function() --点击回调
            if self.togglesData[i].checkFunc and self.togglesData[i].checkFunc(i) == false then
                return
            end
            if i ~= self.selectIndex then --屏蔽掉重复点击当前选择的toggle
                env:FreshSelectStatus(true)
                local preNodeGo = self.Layout:Find("tabGo"..self.selectIndex)
                if preNodeGo then
                    local preNode = GetLuaBehaviour(preNodeGo.gameObject,self.cellEnvPath)
                    preNode.Env:FreshSelectStatus(false)
                end
                self.selectIndex = i
                self.togglesData[i].func(i)
            end
        end)
        KTool.SetActive(tabGo, true)

        --redPointGo = GameUtils.GetRedPointGo(tabGo)
        --if redPointGo then
        --    local hasUnclaimedReward = self:IsDayTaskUnclaimed(i)
        --    KTool.SetActive(redPointGo, hasUnclaimedReward)
        --end

    end

    if self.Layout.transform.childCount > #self.togglesData then
        for i = #self.togglesData + 1, self.Layout.transform.childCount do
            local go = self.Layout:Find("tabGo"..i)
            CfUtils.SetActive(go, false)
        end
    end
end

function CommonTabToggleUp:OnDestroy()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        for k, v in pairs(self.togglesData) do
            if not isNull(v.redPointStrNode) then
                GameUtils.RemoveRedPointCallBack(v.redPointStrNode)
            end
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function CommonTabToggleUp:GetTabNodeByIndex(index)
    return self.Layout:Find("tabGo"..index)
end

---@return CommonTabToggleUpCell
function CommonTabToggleUp:GetTabNodeLuaByIndex(index)
    local node = self:GetTabNodeByIndex(index)
    if isNull(node) then return end

    local env = CfUtils.GetLuaScr(node, self.cellEnvPath)
    return env
end

---设置锁定状态
---@param index integer cellIndex
---@param state boolean 锁定状态
function CommonTabToggleUp:SetLockState(index, state)
    local env = self:GetTabNodeLuaByIndex(index)
    if isNotNull(env) then
        env:SetLockState(state)
    end
end

---设置选中状态
---@param index integer cellIndex 要选中的下标
function CommonTabToggleUp:SetSelectState(index, isTriggerCb)
    local oldEnv = self:GetTabNodeLuaByIndex(self.selectIndex)
    if isNotNull(oldEnv) then 
        oldEnv:FreshSelectStatus(false)
    end
    
    local newEnv = self:GetTabNodeLuaByIndex(index)
    if isNotNull(newEnv) then 
        newEnv:FreshSelectStatus(true)
    end

    self.selectIndex = index

    if isTriggerCb then
        local data = self.togglesData[index]
        if data then
            data.func(index)
        end
    end
end

function CommonTabToggleUp:FreshRedPointStatus(index, isShow)
    local env = self:GetTabNodeLuaByIndex(index)
    if isNotNull(env) then 
        env:FreshRedPointStatus(isShow)
    end
end

function CommonTabToggleUp:RefresCellhName(index, name)
    local env = self:GetTabNodeLuaByIndex(index)
    if isNotNull(env) then 
        env:FreshName(name)
    end
end

return CommonTabToggleUp